/* ════════════════════════════════════════════════
   프롬프트 마스터 — 한국인을 위한 AI 사용법
   ════════════════════════════════════════════════ */
:root {
  --bg: #0b1026;
  --bg-2: #131a3a;
  --card: rgba(255, 255, 255, 0.055);
  --card-strong: rgba(255, 255, 255, 0.09);
  --border: rgba(255, 255, 255, 0.12);
  --text: #eef1ff;
  --text-dim: #aab0d8;
  --cyan: #22d3ee;
  --mint: #34d399;
  --gold: #fbbf24;
  --coral: #fb7185;
  --violet: #a78bfa;
  --grad: linear-gradient(135deg, #22d3ee 0%, #34d399 100%);
  --grad-warm: linear-gradient(135deg, #fbbf24 0%, #fb7185 100%);
  --grad-quiz: linear-gradient(135deg, #a78bfa 0%, #fb7185 100%);
  --radius: 18px;
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.45);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Noto Sans KR', 'Apple SD Gothic Neo', 'Malgun Gothic', 'Noto Sans CJK KR', sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  overflow-x: hidden;
  line-height: 1.55;
}

/* ── 배경 이펙트 ── */
#bg-canvas { position: fixed; inset: 0; z-index: 0; pointer-events: none; }
.bg-orb { position: fixed; border-radius: 50%; filter: blur(90px); opacity: 0.35; z-index: 0; pointer-events: none; animation: orbDrift 18s ease-in-out infinite alternate; }
.orb-1 { width: 480px; height: 480px; background: #1d2a6b; top: -120px; left: -120px; }
.orb-2 { width: 420px; height: 420px; background: #123f4f; bottom: -140px; right: -120px; animation-delay: -6s; }
.orb-3 { width: 300px; height: 300px; background: #3b1d54; top: 40%; left: 60%; animation-delay: -12s; }
@keyframes orbDrift {
  from { transform: translate(0, 0) scale(1); }
  to   { transform: translate(60px, -50px) scale(1.15); }
}

.hidden { display: none !important; }

/* ════════ HUD ════════ */
#hud {
  position: sticky; top: 0; z-index: 50;
  display: flex; align-items: center; gap: 12px;
  padding: 10px 16px;
  background: rgba(11, 16, 38, 0.82);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}
.hud-home { background: var(--card); border: 1px solid var(--border); color: var(--text); font-size: 1.1rem; border-radius: 12px; width: 42px; height: 42px; cursor: pointer; transition: transform .15s, background .2s; }
.hud-home:hover { transform: scale(1.1); background: var(--card-strong); }
.hud-rank { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; }
.hud-rank-emoji { font-size: 1.6rem; }
.hud-rank-info { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.hud-rank-name { font-size: 0.8rem; font-weight: 700; color: var(--cyan); white-space: nowrap; }
.xp-bar { width: min(180px, 34vw); height: 6px; background: rgba(255,255,255,0.1); border-radius: 99px; overflow: hidden; }
.xp-fill { height: 100%; width: 0%; background: var(--grad); border-radius: 99px; transition: width .6s ease; }
.hud-coins { font-weight: 800; color: var(--gold); background: rgba(251,191,36,0.1); border: 1px solid rgba(251,191,36,0.3); padding: 6px 12px; border-radius: 99px; font-size: 0.9rem; white-space: nowrap; }
.hud-mute { background: var(--card); border: 1px solid var(--border); color: var(--text); border-radius: 12px; width: 42px; height: 42px; cursor: pointer; font-size: 1rem; transition: transform .15s; }
.hud-mute:hover { transform: scale(1.1); }

/* ════════ 화면 전환 ════════ */
main#app { position: relative; z-index: 1; }
.screen { display: none; max-width: 1060px; margin: 0 auto; padding: 24px 18px 80px; animation: screenIn .4s ease; }
.screen.active { display: block; }
@keyframes screenIn { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }

.page-head { text-align: center; margin-bottom: 22px; }
.page-head h2 { font-size: clamp(1.5rem, 4vw, 2.1rem); font-weight: 900; }
.page-head p { color: var(--text-dim); margin-top: 6px; font-size: 0.95rem; }

/* ════════ 버튼 ════════ */
.btn {
  font-family: inherit; cursor: pointer; border: none; border-radius: var(--radius);
  font-weight: 800; color: #08111f; transition: transform .15s, box-shadow .2s, filter .2s;
  padding: 13px 22px; font-size: 1rem;
}
.btn:hover { transform: translateY(-2px); filter: brightness(1.08); }
.btn:active { transform: translateY(1px) scale(.98); }
.btn-primary { background: var(--grad); box-shadow: 0 8px 28px rgba(52, 211, 153, .35); }
.btn-quiz { background: var(--grad-quiz); color: #fff; box-shadow: 0 8px 28px rgba(167, 139, 250, .4); }
.btn-send { background: var(--grad-warm); color: #2b1204; box-shadow: 0 8px 28px rgba(251, 113, 133, .4); font-size: 1.05rem; padding: 14px 26px; border-radius: var(--radius); }
.btn-send:disabled { opacity: .35; cursor: not-allowed; transform: none; filter: none; box-shadow: none; }
.btn-ghost { background: var(--card); color: var(--text); border: 1px solid var(--border); }
.btn-ghost:hover { background: var(--card-strong); }
.btn-big { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 16px 22px; text-align: left; }
.btn-big small { font-weight: 500; font-size: .78rem; opacity: .78; }
.btn-small { padding: 9px 14px; font-size: .9rem; }
.full { width: 100%; }

/* ════════ 타이틀 화면 ════════ */
#screen-title { min-height: calc(100vh - 20px); display: none; }
#screen-title.active { display: flex; align-items: center; justify-content: center; }
.title-wrap { display: flex; flex-direction: column; align-items: center; gap: 14px; text-align: center; max-width: 860px; }
.title-badge { font-size: .78rem; letter-spacing: .02em; color: var(--cyan); background: rgba(34,211,238,.1); border: 1px solid rgba(34,211,238,.35); padding: 6px 16px; border-radius: 99px; font-weight: 700; }
.game-title { font-size: clamp(3.2rem, 12vw, 5.2rem); line-height: 1.02; font-weight: 900; letter-spacing: -0.03em; text-shadow: 0 10px 50px rgba(34,211,238,.25); }
.grad-text { background: var(--grad); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.game-subtitle { color: var(--text-dim); font-size: clamp(.92rem, 2.4vw, 1.05rem); }
.game-subtitle strong { color: var(--gold); }

/* ── 마스코트 프롬토 (CSS 아트) ── */
.mascot-stage { position: relative; display: flex; align-items: flex-end; gap: 18px; margin: 4px 0; }
.speech-bubble {
  background: #fff; color: #1b2440; font-size: .82rem; line-height: 1.45;
  padding: 12px 16px; border-radius: 16px; border-bottom-right-radius: 4px;
  max-width: 210px; text-align: left; box-shadow: var(--shadow);
  animation: bubbleFloat 3.5s ease-in-out infinite;
}
.speech-bubble b { color: #0891b2; }
@keyframes bubbleFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
.mascot { position: relative; width: 130px; height: 172px; animation: mascotBob 3s ease-in-out infinite; }
@keyframes mascotBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }
.mascot-antenna { position: absolute; top: 0; left: 50%; transform: translateX(-50%); width: 4px; height: 26px; background: #3b4a7a; border-radius: 4px; }
.mascot-antenna-ball { position: absolute; top: -9px; left: 50%; transform: translateX(-50%); width: 14px; height: 14px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 12px var(--cyan); animation: ballGlow 1.6s ease-in-out infinite; }
@keyframes ballGlow { 0%,100% { box-shadow: 0 0 8px var(--cyan); } 50% { box-shadow: 0 0 20px 4px var(--cyan); } }
.mascot-head {
  position: absolute; top: 26px; left: 50%; transform: translateX(-50%);
  width: 108px; height: 88px; border-radius: 30px;
  background: linear-gradient(160deg, #f4f7ff 0%, #c6cdea 55%, #8b97bd 100%);
  box-shadow: inset -6px -8px 14px rgba(30,40,80,.35), inset 5px 6px 10px rgba(255,255,255,.9), 0 10px 30px rgba(0,0,0,.4);
  display: flex; align-items: center; justify-content: center; gap: 20px;
}
.mascot-eye { width: 16px; height: 20px; border-radius: 50%; background: radial-gradient(circle at 38% 38%, #7ff3ff, #0891b2 70%); box-shadow: 0 0 10px rgba(34,211,238,.8); animation: eyeBlink 4.2s infinite; }
@keyframes eyeBlink { 0%, 92%, 100% { transform: scaleY(1); } 96% { transform: scaleY(.08); } }
.mascot-mouth { position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); width: 34px; height: 12px; border: 3px solid #3b4a7a; border-top: none; border-radius: 0 0 30px 30px; }
.mascot-cheek { position: absolute; bottom: 22px; width: 12px; height: 7px; border-radius: 50%; background: rgba(251,113,133,.55); }
.mascot-cheek.left { left: 10px; } .mascot-cheek.right { right: 10px; }
.mascot-body {
  position: absolute; bottom: 0; left: 50%; transform: translateX(-50%);
  width: 88px; height: 58px; border-radius: 18px 18px 22px 22px;
  background: linear-gradient(160deg, #dde4fb 0%, #9aa6cf 60%, #6c78a3 100%);
  box-shadow: inset -5px -6px 10px rgba(30,40,80,.4), inset 4px 5px 8px rgba(255,255,255,.85);
  display: flex; align-items: center; justify-content: center;
}
.mascot-core { font-weight: 900; font-size: 1rem; color: #08111f; background: var(--grad); width: 40px; height: 28px; border-radius: 8px; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 14px rgba(52,211,153,.6); letter-spacing: .05em; }
.mascot-shadow { position: absolute; bottom: -16px; left: 50%; transform: translateX(-50%); width: 90px; height: 12px; background: radial-gradient(ellipse, rgba(0,0,0,.5), transparent 70%); animation: shadowPulse 3s ease-in-out infinite; }
@keyframes shadowPulse { 0%,100% { transform: translateX(-50%) scale(1); opacity:.7; } 50% { transform: translateX(-50%) scale(.8); opacity:.4; } }

.title-buttons { display: flex; flex-direction: column; gap: 12px; width: min(420px, 92vw); }
.title-buttons-row { display: flex; gap: 12px; }
.title-buttons-row .btn { flex: 1; }
.title-stats { color: var(--text-dim); font-size: .8rem; }
.title-stats b { color: var(--gold); }

/* ════════ 스토리 맵 ════════ */
#chapter-list { display: flex; flex-direction: column; gap: 22px; }
.chapter-card { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; backdrop-filter: blur(8px); }
.chapter-head { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; }
.chapter-emoji { font-size: 1.8rem; background: var(--card-strong); border-radius: 14px; width: 56px; height: 56px; display: flex; align-items: center; justify-content: center; }
.chapter-name { font-weight: 900; font-size: 1.1rem; }
.chapter-desc { color: var(--text-dim); font-size: .82rem; }
.level-nodes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.level-node {
  position: relative; background: var(--card-strong); border: 1px solid var(--border);
  border-radius: 16px; padding: 14px 8px 12px; text-align: center; cursor: pointer;
  font-family: inherit; color: var(--text); transition: transform .2s, border-color .2s, box-shadow .2s;
  display: flex; flex-direction: column; align-items: center; gap: 6px;
}
.level-node:hover:not(:disabled) { transform: translateY(-4px); border-color: var(--cyan); box-shadow: 0 10px 30px rgba(34,211,238,.2); }
.level-node:disabled { opacity: .4; cursor: not-allowed; }
.level-node-num { position: absolute; top: 8px; left: 10px; font-size: .7rem; font-weight: 800; color: var(--text-dim); }
.level-node-emoji { font-size: 2rem; }
.level-node-title { font-size: .78rem; font-weight: 700; min-height: 2.4em; display: flex; align-items: center; }
.level-node-stars { color: var(--gold); font-size: .85rem; letter-spacing: 2px; min-height: 1.1em; }
.level-node-stars .empty { color: rgba(255,255,255,.18); }
.level-node.completed { border-color: rgba(52,211,153,.45); }

/* ════════ 레벨 플레이 ════════ */
.level-topbar { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 16px; }
.level-title { font-weight: 900; font-size: 1.05rem; text-align: center; }
.level-chip { font-size: .72rem; font-weight: 800; color: var(--violet); background: rgba(167,139,250,.12); border: 1px solid rgba(167,139,250,.35); padding: 5px 12px; border-radius: 99px; white-space: nowrap; }
.stage { display: none; animation: screenIn .35s ease; }
.stage.active { display: block; }

.situation-card { display: flex; align-items: center; gap: 16px; background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; }
.character-avatar { font-size: 4rem; width: 96px; height: 96px; border-radius: 24px; background: var(--card-strong); display: flex; align-items: center; justify-content: center; animation: mascotBob 3s ease-in-out infinite; }
.character-name { font-weight: 900; font-size: 1.25rem; }
.character-role { color: var(--cyan); font-size: .85rem; font-weight: 700; }
.dialogue-box, .goal-box { margin-top: 14px; background: var(--card); border: 1px solid var(--border); border-left: 4px solid var(--cyan); padding: 16px 18px; border-radius: 14px; }
.goal-box { border-left-color: var(--gold); }
.dialogue-label, .goal-label { font-size: .75rem; font-weight: 800; color: var(--text-dim); margin-bottom: 6px; letter-spacing: .04em; }
.goal-box p { color: #ffe9a8; font-weight: 600; }
#btn-situation-go { margin-top: 18px; justify-content: center; align-items: center; text-align: center; }

/* ── 프롬프트 조립 ── */
.build-formula { text-align: center; color: var(--text-dim); font-size: .9rem; background: var(--card); border: 1px dashed var(--border); padding: 10px; border-radius: 12px; margin-bottom: 14px; }
.build-formula b { color: var(--gold); }
.slot-block { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 12px 14px; margin-bottom: 12px; transition: border-color .25s, box-shadow .25s; }
.slot-block.filled { border-color: rgba(52,211,153,.5); box-shadow: 0 0 0 1px rgba(52,211,153,.25) inset; }
.slot-head { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.slot-icon { font-size: 1.3rem; }
.slot-name { font-weight: 900; font-size: .95rem; }
.slot-desc { color: var(--text-dim); font-size: .72rem; }
.slot-check { margin-left: auto; color: var(--mint); font-weight: 900; opacity: 0; transition: opacity .2s; }
.slot-block.filled .slot-check { opacity: 1; }
.slot-options { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 6px; scrollbar-width: thin; }
.slot-option {
  flex: 0 0 auto; max-width: 230px; text-align: left; font-family: inherit; font-size: .8rem; line-height: 1.45;
  background: var(--card-strong); color: var(--text); border: 1.5px solid transparent; border-radius: 12px;
  padding: 10px 12px; cursor: pointer; transition: border-color .2s, background .2s, transform .15s;
}
.slot-option:hover { transform: translateY(-2px); border-color: var(--cyan); }
.slot-option.selected { border-color: var(--mint); background: rgba(52,211,153,.14); box-shadow: 0 0 18px rgba(52,211,153,.25); }
.build-footer { position: sticky; bottom: 12px; display: flex; align-items: center; gap: 14px; background: rgba(19,26,58,.9); backdrop-filter: blur(12px); border: 1px solid var(--border); border-radius: var(--radius); padding: 12px 16px; margin-top: 6px; z-index: 10; }
.build-progress { flex: 1; }
.build-progress span { font-size: .75rem; color: var(--text-dim); font-weight: 700; }
.build-progress-fill { height: 8px; border-radius: 99px; background: var(--grad); width: 0%; transition: width .3s ease; margin-bottom: 4px; }

/* ── AI 응답 창 ── */
.ai-window { background: #0d1330; border: 1px solid rgba(34,211,238,.3); border-radius: var(--radius); overflow: hidden; box-shadow: 0 0 40px rgba(34,211,238,.12), var(--shadow); }
.ai-window-bar { display: flex; align-items: center; gap: 7px; background: rgba(255,255,255,.04); padding: 10px 14px; border-bottom: 1px solid var(--border); }
.dot { width: 11px; height: 11px; border-radius: 50%; }
.dot.red { background: #fb7185; } .dot.yellow { background: #fbbf24; } .dot.green { background: #34d399; }
.ai-window-title { margin-left: 8px; font-size: .75rem; color: var(--text-dim); font-weight: 700; }
.ai-response { padding: 18px; min-height: 130px; white-space: pre-wrap; font-size: .93rem; line-height: 1.75; color: #d7f9f0; }
.caret { animation: caretBlink .8s steps(1) infinite; color: var(--mint); }
@keyframes caretBlink { 50% { opacity: 0; } }

.followup-panel { margin-top: 16px; background: var(--card); border: 1px solid rgba(251,191,36,.35); border-radius: var(--radius); padding: 16px; animation: screenIn .4s ease; }
.followup-label { font-size: .85rem; color: var(--gold); margin-bottom: 8px; }
.followup-question { font-weight: 800; margin-bottom: 10px; }
.followup-options { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 8px; }
