/* ════════ 토스트 ════════ */
.toast { position: fixed; bottom: 28px; left: 50%; transform: translate(-50%, 20px); z-index: 200; background: #1c2450; border: 1px solid var(--cyan); color: var(--text); padding: 10px 20px; border-radius: 99px; font-size: .85rem; font-weight: 700; opacity: 0; pointer-events: none; transition: opacity .25s, transform .25s; }
